--
-- Застосування (phpMyAdmin хостингу): вкладка SQL → вставити вміст файлу → Вперёд.
-- Безпечно: лише INSERT IGNORE з фіксованими id продуктів/тарифів; підкатегорії
-- шукаються за slug (id таксономії на хостингу й локально можуть відрізнятись).
-- Жодних DROP / DELETE / перестворення таблиць.
-- Ціни й факти — лише зі сторінок продуктів станом на 2026-09-21; непідтверджене
-- (ціни Fi, Pawp, Wag-планів, Navfarm, BeeScanning, Paprika, Cookpad тощо) лишено порожнім.
-- =====================================================================

SET @cat_home := (SELECT `id` FROM `categories` WHERE `slug` = 'my-home' LIMIT 1);
SET @sub_pets := (SELECT `id` FROM `subcategories` WHERE `slug` = 'pets' AND `category_id` = @cat_home LIMIT 1);
SET @sub_livestock := (SELECT `id` FROM `subcategories` WHERE `slug` = 'livestock' AND `category_id` = @cat_home LIMIT 1);
SET @sub_poultry := (SELECT `id` FROM `subcategories` WHERE `slug` = 'poultry' AND `category_id` = @cat_home LIMIT 1);
SET @sub_fish := (SELECT `id` FROM `subcategories` WHERE `slug` = 'fish' AND `category_id` = @cat_home LIMIT 1);
SET @sub_beekeeping := (SELECT `id` FROM `subcategories` WHERE `slug` = 'beekeeping' AND `category_id` = @cat_home LIMIT 1);
SET @sub_cooking := (SELECT `id` FROM `subcategories` WHERE `slug` = 'cooking' AND `category_id` = @cat_home LIMIT 1);
SET @sub_pet_grooming_vet := (SELECT `id` FROM `subcategories` WHERE `slug` = 'pet-grooming-vet' AND `category_id` = @cat_home LIMIT 1);

